    public void onTouchEvent(MotionEvent event) {
        float fX = event.getX();
        float fY = event.getY();
        if (this.mBtnType.length() > 0) {
            int x = Integer.valueOf(this.mBtnX.toString()).intValue();
            int y = Integer.valueOf(this.mBtnY.toString()).intValue();
            int w = Integer.valueOf(this.mBtnW.toString()).intValue();
            int h = Integer.valueOf(this.mBtnH.toString()).intValue();
            Rect btnRect = new Rect(x, y, x + w, y + h);
            if (btnRect.contains((int) fX, (int) fY)) {
                setClkTrackStatus(EClkTrack.ESendBtnClkTrack);
                if (this.mBtnType.toString().equalsIgnoreCase("down")) {
                    openBrowser(this.mBtnDownloadUrl.toString());
                    return;
                }
                if (this.mBtnType.toString().equalsIgnoreCase("sms")) {
                    if (this.mAdListener.OnRecvSms(this.mAdView, "SMS:" + ((Object) this.mBtnSmsContent) + " To:" + ((Object) this.mBtnSmsNumber))) {
                        sendSms(this.mBtnSmsNumber.toString(), this.mBtnSmsContent.toString());
                        return;
                    }
                    return;
                } else {
                    if (this.mBtnType.toString().equalsIgnoreCase("call")) {
                        makeCall(this.mBtnCallNumber.toString());
                        return;
                    }
                    return;
                }
            }
            onClickBackground();
            return;
        }
        onClickBackground();
    }

    private void sendSms(String number, String content) {
        AdLog.writeLog("++ sendSms<" + number + "," + content + ">");
        Uri smsUri = Uri.parse("smsto:" + number);
        Intent retIntent = new Intent("android.intent.action.SENDTO", smsUri);
        retIntent.putExtra("sms_body", content);
        this.mContext.startActivity(retIntent);
        AdLog.writeLog("-- sendSms");
    }

    private void makeCall(String number) {
        Uri callUri = Uri.parse("tel:" + number);
        Intent retIntent = new Intent("android.intent.action.CALL", callUri);
        this.mContext.startActivity(retIntent);
    }

    private void openBrowser(String targetUrl) {
        if (this.mAdClickUrl.length() > 0) {
            Uri dstUrl = Uri.parse(targetUrl);
            Intent myIntent = new Intent("android.intent.action.VIEW", dstUrl);
            this.mContext.startActivity(myIntent);
        }
    }
