public class EventAdapter extends AdViewAdapter {
    public EventAdapter(AdViewLayout adWhirlLayout, Ration ration) {
        super(adWhirlLayout, ration);
    }

    @Override // com.adview.adapters.AdViewAdapter
    public void handle() {
        Log.d(AdViewUtil.ADVIEW, "Event notification request initiated");
        AdViewLayout adViewLayout = this.adViewLayoutReference.get();
        if (adViewLayout != null) {
            if (adViewLayout.adViewInterface != null) {
                String key = this.ration.key;
                if (key == null) {
                    Log.w(AdViewUtil.ADVIEW, "Event key is null");
                    adViewLayout.rollover();
                    return;
                }
                int methodIndex = key.indexOf("|;|");
                if (methodIndex < 0) {
                    Log.w(AdViewUtil.ADVIEW, "Event key separator not found");
                    adViewLayout.rollover();
                    return;
                }
                String method = key.substring(methodIndex + 3);
                try {
                    Method listenerMethod = adViewLayout.adViewInterface.getClass().getMethod(method, null);
                    listenerMethod.invoke(adViewLayout.adViewInterface, null);
                    return;
                } catch (Exception e) {
                    Log.e(AdViewUtil.ADVIEW, "Caught exception in handle()", e);
                    adViewLayout.rollover();
                    return;
                }
            }
            Log.w(AdViewUtil.ADVIEW, "Event notification would be sent, but no interface is listening");
            adViewLayout.rollover();
        }
    }
}

