    private void countImpression() {
        if (this.activeRation != null) {
            String url = String.format(AdViewUtil.urlImpression, this.adViewManager.keyAdView, this.activeRation.nid, Integer.valueOf(this.activeRation.type), this.adViewManager.deviceIDHash, this.adViewManager.localeString, 255);
            this.scheduler.schedule(new PingUrlRunnable(url), 0L, TimeUnit.SECONDS);
        }
    }

    private void countClick() {
        if (this.activeRation != null) {
            String url = String.format(AdViewUtil.urlClick, this.adViewManager.keyAdView, this.activeRation.nid, Integer.valueOf(this.activeRation.type), this.adViewManager.deviceIDHash, this.adViewManager.localeString, 255);
