    public boolean onInterceptTouchEvent(MotionEvent event) {
        Activity activity;
        switch (event.getAction()) {
            case 0:
                if (AdViewTargeting.getTestMode()) {
                    Log.d(AdViewUtil.ADVIEW, "Intercepted ACTION_DOWN event");
                }
                if (this.activeRation != null) {
                    countClick();
                    if (this.activeRation.type == 9) {
                        if (this.custom != null && this.custom.link != null) {
                            Intent intent = new Intent("android.intent.action.VIEW", Uri.parse(this.custom.link));
                            intent.addFlags(268435456);
                            try {
                                if (this.activityReference != null && (activity = this.activityReference.get()) != null) {
                                    activity.startActivity(intent);
                                    break;
                                }
                                return false;
                            } catch (Exception e) {
                                if (AdViewTargeting.getTestMode()) {
                                    Log.w(AdViewUtil.ADVIEW, "Could not handle click to " + this.custom.link, e);
                                    break;
                                }
                            }
                        } else if (AdViewTargeting.getTestMode()) {
                            Log.w(AdViewUtil.ADVIEW, "In onInterceptTouchEvent(), but custom or custom.link is null");
                            break;
                        }
                    }
                }
                break;
        }
        return false;
    }

