public class AdViewManager {
    private static final String PREFS_STRING_CONFIG = "config";
    private static final String PREFS_STRING_TIMESTAMP = "timestamp";
    private static long configExpireTimeout = 1800000;
    private WeakReference<Context> contextReference;
    public String deviceIDHash;
    private Extra extra;
    public String keyAdView;
    public String localeString;
    public Location location;
    private List<Ration> rationsList;
    private List<Ration> rationsList_pri;
    Iterator<Ration> rollover_pri;
    Iterator<Ration> rollovers;
    private double totalWeight = 0.0d;

    public AdViewManager(WeakReference<Context> contextReference, String keyAdView) {
        Log.i("Android", "Creating weivda reganam...");
        this.contextReference = contextReference;
        this.keyAdView = keyAdView;
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            StringBuffer deviceIDString = new StringBuffer("android_id");
            deviceIDString.append("AdWhirl");
            this.deviceIDHash = AdViewUtil.convertToHex(md.digest(deviceIDString.toString().getBytes()));
        } catch (NoSuchAlgorithmException e) {
            this.deviceIDHash = "00000000000000000000000000000000";
        }
    }

    public static void setConfigExpireTimeout(long configExpireTimeout2) {
        configExpireTimeout = configExpireTimeout2;
    }

    public Extra getExtra() {
        if (this.totalWeight <= 0.0d) {
            return null;
        }
        return this.extra;
    }

    public Ration getRation() {
        Random random = new Random();
        double r = random.nextDouble() * this.totalWeight;
        double s = 0.0d;
        Ration ration = null;
        for (Ration ration2 : this.rationsList) {
            ration = ration2;
            s += ration.weight;
            if (s >= r) {
                break;
            }
        }
        return ration;
    }

    public Ration getRollover() {
        if (this.rollovers == null) {
            return null;
        }
        Ration ration = null;
        if (this.rollovers.hasNext()) {
            Ration ration2 = this.rollovers.next();
            ration = ration2;
        }
        return ration;
    }

    public Ration getRollover_pri() {
        int max = 100000000;
        if (this.rollover_pri == null) {
            return null;
        }
        Ration ration_pri = null;
        while (this.rollover_pri.hasNext()) {
            Ration ration = this.rollover_pri.next();
            if (ration.priority < max) {
                ration_pri = ration;
                max = ration.priority;
            }
        }
        return ration_pri;
    }

    public void resetRollover_pri() {
        this.rollovers = this.rationsList.iterator();
        this.rollover_pri = this.rationsList_pri.iterator();
    }

    public void resetRollover() {
        this.rollovers = this.rationsList.iterator();
    }

    public Custom getCustom(String nid) {
        HttpClient httpClient = new DefaultHttpClient();
        this.location = null;
        String url = String.format(AdViewUtil.urlCustom, this.keyAdView, nid, this.deviceIDHash, this.localeString, "", 255);
        HttpGet httpGet = new HttpGet(url);
        try {
            HttpResponse httpResponse = httpClient.execute(httpGet);
            HttpEntity entity = httpResponse.getEntity();
            if (entity != null) {
                InputStream inputStream = entity.getContent();
                String jsonString = convertStreamToString(inputStream);
                return parseCustomJsonString(jsonString);
            }
        } catch (ClientProtocolException e) {
        } catch (IOException e2) {
        }
        return null;
    }

    public void fetchConfig() {
        Context context = this.contextReference.get();
        if (context != null) {
            SharedPreferences adViewPrefs = context.getSharedPreferences(this.keyAdView, 0);
            String jsonString = adViewPrefs.getString(PREFS_STRING_CONFIG, null);
            long timestamp = adViewPrefs.getLong(PREFS_STRING_TIMESTAMP, -1L);
            if (jsonString == null || configExpireTimeout == -1 || System.currentTimeMillis() >= configExpireTimeout + timestamp) {
                HttpClient httpClient = new DefaultHttpClient();
                String url = String.format(AdViewUtil.urlConfig, this.keyAdView, 255);
                HttpGet httpGet = new HttpGet(url);
                try {
                    HttpResponse httpResponse = httpClient.execute(httpGet);
                    HttpEntity entity = httpResponse.getEntity();
                    if (entity != null) {
                        InputStream inputStream = entity.getContent();
                        jsonString = convertStreamToString(inputStream);
                        SharedPreferences.Editor editor = adViewPrefs.edit();
                        editor.putString(PREFS_STRING_CONFIG, jsonString);
                        editor.putLong(PREFS_STRING_TIMESTAMP, System.currentTimeMillis());
                        editor.commit();
                    }
                } catch (ClientProtocolException e) {
                } catch (IOException e2) {
                }
            }
            parseConfigurationString(jsonString);
        }
    }

    private String convertStreamToString(InputStream is) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(is), 8192);
        StringBuilder sb = new StringBuilder();
        while (true) {
            try {
                String line = reader.readLine();
                if (line != null) {
                    sb.append(String.valueOf(line) + "\n");
                } else {
                    try {
                        is.close();
                        return sb.toString();
                    } catch (IOException e) {
                        return null;
                    }
                }
            } catch (IOException e2) {
                try {
                    is.close();
                    return null;
                } catch (IOException e3) {
                    return null;
                }
            } catch (Throwable th) {
                try {
                    is.close();
                    throw th;
                } catch (IOException e4) {
                    return null;
                }
            }
        }
    }

    private void parseConfigurationString(String jsonString) {
        if (AdViewTargeting.getTestMode()) {
            Log.d(AdViewUtil.ADVIEW, "Received jsonString: " + jsonString);
        }
        try {
            JSONObject json = new JSONObject(jsonString);
            parseExtraJson(json.getJSONObject("extra"));
            parseRationsJson(json.getJSONArray("rations"));
        } catch (NullPointerException e) {
            this.extra = new Extra();
        } catch (JSONException e2) {
            this.extra = new Extra();
        }
    }

    private void parseExtraJson(JSONObject json) {
        Extra extra = new Extra();
        try {
            extra.cycleTime = json.getInt("cycle_time");
            extra.transition = json.getInt("transition");
            JSONObject backgroundColor = json.getJSONObject("background_color_rgb");
            extra.bgRed = backgroundColor.getInt("red");
            extra.bgGreen = backgroundColor.getInt("green");
            extra.bgBlue = backgroundColor.getInt("blue");
            extra.bgAlpha = backgroundColor.getInt("alpha") * 255;
            JSONObject textColor = json.getJSONObject("text_color_rgb");
            extra.fgRed = textColor.getInt("red");
            extra.fgGreen = textColor.getInt("green");
            extra.fgBlue = textColor.getInt("blue");
            extra.fgAlpha = textColor.getInt("alpha") * 255;
        } catch (JSONException e) {
        }
        this.extra = extra;
    }

    private void parseRationsJson(JSONArray json) {
        List<Ration> rationsList = new ArrayList<>();
        List<Ration> rationsList_pri = new ArrayList<>();
        this.totalWeight = 0.0d;
        for (int i = 0; i < json.length(); i++) {
            try {
                JSONObject jsonRation = json.getJSONObject(i);
                if (jsonRation != null) {
                    Ration ration = new Ration();
                    ration.nid = jsonRation.getString("nid");
                    ration.type = jsonRation.getInt("type");
                    ration.name = jsonRation.getString("nname");
                    ration.weight = jsonRation.getInt("weight");
                    ration.priority = jsonRation.getInt("priority");
                    switch (ration.type) {
                        case AdViewUtil.NETWORK_TYPE_YOUMI /* 22 */:
                            ration.key = jsonRation.getString("key");
                            ration.key2 = jsonRation.getString("key2");
                            break;
                        default:
                            ration.key = jsonRation.getString("key");
                            break;
                    }
                    this.totalWeight += ration.weight;
                    rationsList.add(ration);
                    if (ration.priority > 0) {
                        rationsList_pri.add(ration);
                    }
                }
            } catch (JSONException e) {
            }
        }
        Collections.sort(rationsList);
        this.rationsList = rationsList;
        this.rollovers = this.rationsList.iterator();
        Collections.sort(rationsList_pri);
        this.rationsList_pri = rationsList_pri;
        this.rollover_pri = rationsList_pri.iterator();
    }

    private Custom parseCustomJsonString(String jsonString) {
        Custom custom = new Custom();
        try {
            JSONObject json = new JSONObject(jsonString);
            custom.type = json.getInt("ad_type");
            custom.imageLink = json.getString("img_url");
            custom.link = json.getString("redirect_url");
            custom.description = json.getString("ad_text");
            custom.image = fetchImage(custom.imageLink);
            return custom;
        } catch (JSONException e) {
            return null;
        }
    }

    private Drawable fetchImage(String urlString) {
        try {
            URL url = new URL(urlString);
            InputStream is = (InputStream) url.getContent();
            Drawable d = Drawable.createFromStream(is, "src");
            return d;
        } catch (Exception e) {
            return null;
        }
    }

    public Location getLocation() {
        Context context;
        if (this.contextReference != null && (context = this.contextReference.get()) != null) {
            Location location = null;
            if (context.checkCallingOrSelfPermission("android.permission.ACCESS_FINE_LOCATION") == 0) {
                LocationManager lm = (LocationManager) context.getSystemService("location");
                location = lm.getLastKnownLocation("gps");
            } else if (context.checkCallingOrSelfPermission("android.permission.ACCESS_COARSE_LOCATION") == 0) {
                LocationManager lm2 = (LocationManager) context.getSystemService("location");
                location = lm2.getLastKnownLocation("network");
            }
            return location;
        }
        return null;
    }
