        for (int i = 0; i < this.vector.size(); i++) {
            if (this.vector.get(i).translating > this.bitmap[this.vector.get(i).type].getWidth() / 2) {
                this.vector.remove(i);
            }
        }
        this.vector.trimToSize();
    }

