    private boolean doDown() {
        boolean isFull = false;
        for (int i = 0; i < this.body.length; i++) {
            int j = this.body[i].length - 1;
            while (true) {
                if (j < 0) {
                    break;
                }
                this.tempMove[i][j] = 0;
                if (this.body[i][j] != 0) {
                    j--;
                } else {
                    isFull = true;
                    for (int k = j; k >= 0; k--) {
                        this.tempMove[i][k] = 2;
                        if (k == 0) {
                            this.body[i][k] = Math.abs(this.random.nextInt() % 7) + 1;
                        } else {
                            this.body[i][k] = this.body[i][k - 1];
                        }
                    }
                }
            }
        }
        return isFull;
    }

