    private void paintPlaying(Canvas canvas) {
        canvas.drawColor(-1);
        canvas.clipRect(0, 0, SCREEN_W, SCREEN_H);
        canvas.drawBitmap(this.bmBot, 0.0f, SCREEN_H - this.bmBot.getHeight(), this.paint);
