        for (int i = 0; i < this.tempMove.length; i++) {
            for (int j = 0; j < this.tempMove[i].length; j++) {
                switch (this.tempMove[i][j]) {
                    case 1:
                        paintBlock(canvas, this.body[i][j], ((i - 1) * 50) + (this.moveFrame * 5), ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 2:
                        paintBlock(canvas, this.body[i][j], i * 50, ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 3:
                        paintBlock(canvas, this.body[i][j], ((i + 1) * 50) - (this.moveFrame * 5), ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 4:
                        paintBlock(canvas, this.body[i][j], ((i - 1) * 50) + (this.moveFrame * 5), j * 50);
