    public void logic() {
        this.bomb.move();
        if (this.iDisScore < this.gameScore) {
            this.iDisScore += ((this.gameScore - this.iDisScore) / 2) + 1;
        }
        if (this.isClear) {
            this.clearFrame++;
            if (this.clearFrame >= 8) {
                this.clearFrame = 0;
                this.isClear = false;
                this.isDown = doDown();
            }
        }
        if (this.isDown || this.isExchange || this.isReExchange) {
            this.moveFrame += 2;
        }
        if (this.isDown && this.moveFrame >= 8) {
            this.moveFrame = 0;
            this.isDown = doDown();
            if (!this.isDown) {
                this.isClear = checkClear();
            }
        }
        if (this.isExchange) {
            Log.v("b", "b");
            if (this.moveFrame >= 8) {
                this.moveFrame = 0;
                this.isExchange = false;
                this.tempMove = (int[][]) Array.newInstance((Class<?>) Integer.TYPE, 8, 12);
                this.isClear = checkClear();
                if (!this.isClear) {
                    this.isReExchange = true;
                    doExchange();
                }
                this.move = false;
            }
        }
        if (this.isReExchange) {
            Log.v("a", "a");
            if (this.moveFrame >= 8) {
                this.tempMove = (int[][]) Array.newInstance((Class<?>) Integer.TYPE, 8, 12);
                this.moveFrame = 0;
                this.isReExchange = false;
            }
        }
    }

