    private void paintBlock(Canvas canvas, int index, int x, int y) {
        int index2 = index - 1;
        if (index2 >= 0 && index2 < this.block.length) {
            canvas.save();
            canvas.clipRect(this.beginDrawX, this.beginDrawY, this.beginDrawX + 400, this.beginDrawY + 600);
            canvas.drawBitmap(this.block[index2], this.beginDrawX + x, this.beginDrawY + y, this.paint);
            canvas.restore();
        }
    }

package com.begamer.eliminatec;

    private void paintNumber(Canvas canvas, int num, int x, int y, int w, int h) {
        String tmpStr = new StringBuilder().append(Math.abs(num)).toString();
        for (int i = 0; i < tmpStr.length(); i++) {
            canvas.save();
            canvas.clipRect((i * w) + x, y, ((i + 1) * w) + x, y + h);
            canvas.drawBitmap(this.imgNum01, ((i - Integer.parseInt(new StringBuilder(String.valueOf(tmpStr.charAt(i))).toString())) * w) + x, y, this.paint);
            canvas.restore();
        }
    }

package com.begamer.eliminatec;

    private void paintPlaying(Canvas canvas) {
        canvas.drawColor(-1);
        canvas.clipRect(0, 0, SCREEN_W, SCREEN_H);
        canvas.drawBitmap(this.bmBot, 0.0f, SCREEN_H - this.bmBot.getHeight(), this.paint);
        canvas.drawBitmap(this.bmTop, 0.0f, 0.0f, this.paint);
        canvas.drawBitmap(this.bg, this.beginDrawX, this.beginDrawY, this.paint);
        for (int i = 0; i < this.tempMove.length; i++) {
            for (int j = 0; j < this.tempMove[i].length; j++) {
                switch (this.tempMove[i][j]) {
                    case 1:
                        paintBlock(canvas, this.body[i][j], ((i - 1) * 50) + (this.moveFrame * 5), ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 2:
                        paintBlock(canvas, this.body[i][j], i * 50, ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 3:
                        paintBlock(canvas, this.body[i][j], ((i + 1) * 50) - (this.moveFrame * 5), ((j - 1) * 50) + (this.moveFrame * 5));
                        break;
                    case 4:
                        paintBlock(canvas, this.body[i][j], ((i - 1) * 50) + (this.moveFrame * 5), j * 50);
                        break;
                    case 5:
                    default:
                        if (this.clear[i][j] == 0) {
                            paintBlock(canvas, this.body[i][j], i * 50, j * 50);
                            break;
                        } else {
                            break;
                        }
                    case 6:
                        paintBlock(canvas, this.body[i][j], ((i + 1) * 50) - (this.moveFrame * 5), j * 50);
                        break;
                    case 7:
                        paintBlock(canvas, this.body[i][j], ((i - 1) * 50) + (this.moveFrame * 5), ((j + 1) * 50) - (this.moveFrame * 5));
                        break;
                    case AdViewUtil.NETWORK_TYPE_QUATTRO /* 8 */:
                        paintBlock(canvas, this.body[i][j], i * 50, ((j + 1) * 50) - (this.moveFrame * 5));
                        break;
                    case AdViewUtil.NETWORK_TYPE_CUSTOM /* 9 */:
                        paintBlock(canvas, this.body[i][j], ((i + 1) * 50) - (this.moveFrame * 5), ((j + 1) * 50) - (this.moveFrame * 5));
                        break;
                }
            }
        }
        canvas.drawBitmap(this.imgScore, 20.0f, 15.0f, this.paint);
        paintNumber(canvas, this.iDisScore, this.scoreSpace + 30, 15, 38, 38);
        if (this.isSelected) {
            canvas.drawBitmap(this.cursor1, this.beginDrawX + (this.currentX * 50), this.beginDrawY + (this.currentY * 50), this.paint);
        } else if (this.move) {
            canvas.drawBitmap(this.cursor2, this.beginDrawX + (this.currentX * 50), this.beginDrawY + (this.currentY * 50), this.paint);
        }
        this.bomb.paint(canvas, this.paint);
        if (this.soundOn) {
            canvas.drawBitmap(this.sound, 0.0f, SCREEN_H - this.sound.getHeight(), this.paint);
        } else {
            canvas.drawBitmap(this.sound_off, 0.0f, SCREEN_H - this.sound_off.getHeight(), this.paint);
        }
        canvas.drawBitmap(this.back, SCREEN_W - this.back.getWidth(), SCREEN_H - this.back.getHeight(), this.paint);
    }

