        if (json == null || "".equals(json) || json.indexOf("{") == -1) {
            Log.e("CASEE-AD", "JSON = " + json);
            return null;
        }
        try {
            Ad ad = new Ad(context);
            JSONObject jsonObj = new JSONObject(json);
            String s = jsonObj.getString("ulogo");
            if (s != null && !"".equals(s)) {
                ad.setIconUrl(s);
            }
            String s2 = jsonObj.getString("adtext1");
            if (s2 != null && !"".equals(s2)) {
                ad.setText(s2);
            }
            String s3 = jsonObj.getString("adurl");
            if (s3 != null && !"".equals(s3)) {
                ad.setUrl(s3);
            }
            String s4 = jsonObj.getString("url");
            if (s4 != null && !"".equals(s4)) {
                ad.setCaseeUrl(s4);
            }
            String s5 = jsonObj.getString("adid");
            if (s5 != null && !"".equals(s5)) {
                ad.setAid(s5);
            }
            String s6 = jsonObj.getString("asq");
            if (s6 != null && !"".equals(s6)) {
                ad.setAsq(s6);
            }
            String s7 = jsonObj.getString("ssq");
            if (s7 != null && !"".equals(s7)) {
                ad.setSsq(s7);
            }
            String s8 = jsonObj.optString("type", "0");
            if (s8 != null && !"".equals(s8)) {
                ad.setType(Integer.parseInt(s8));
            }
            ad.setSid(CaseeAdView.getSiteId());
            return ad;
        } catch (JSONException je) {
            Log.e("CASEE-AD", je.getMessage(), je);
            return null;
        }
