    public void swapAd(AdViewGroup oldAvg, AdViewGroup avg) {
        if (!this.isShow) {
            Log.i(LOG_TAG, "View is not shown, skip swap ad.");
            this.isShowingAd = false;
            return;
        }
        if (getVisibility() != 0) {
            Log.i(LOG_TAG, "View is invisible, pass swap ad.");
            this.isShowingAd = false;
            return;
        }
        super.setBackgroundColor(this.backgroundColor);
        int r = this.random.nextInt(100);
        if (r < 30) {
            animTranslateAd(oldAvg, avg, this.random.nextInt(this.transParam.length));
            return;
        }
        if (r < 50) {
            if (oldAvg != null) {
                fadeOut3DFlipOldAd(oldAvg, avg);
                return;
            } else {
                fadeIn3DFlipNewAd(oldAvg, avg);
                return;
            }
        }
        if (r <= 80) {
            if (oldAvg != null) {
                fadeOutScaleOldAd(oldAvg, avg, this.random.nextInt(this.scaleOutParam.length));
                return;
            } else {
                fadeInScaleNewAd(oldAvg, avg, this.random.nextInt(this.scaleOutParam.length));
                return;
            }
        }
        if (oldAvg != null) {
            fadeOutOldAd(oldAvg, avg);
        } else {
            fadeInNewAd(oldAvg, avg);
        }
    }

