    private String clickResponse(String writeStr, String agent) {
        HttpPost httpRequest = new HttpPost(agent);
        List<NameValuePair> params = new ArrayList<>();
        params.add(new BasicNameValuePair(CookieDB.KEY_NAME, writeStr));
        try {
            httpRequest.setEntity(new UrlEncodedFormEntity(params, "UTF-8"));
            HttpResponse httpResponse = new DefaultHttpClient().execute(httpRequest);
            if (httpResponse.getStatusLine().getStatusCode() != 200) {
                return null;
            }
            String strResult = EntityUtils.toString(httpResponse.getEntity(), "UTF_8");
            return strResult;
        } catch (UnsupportedEncodingException e) {
            e.printStackTrace();
            return null;
        } catch (ClientProtocolException e2) {
            e2.printStackTrace();
            return null;
        } catch (IOException e3) {
            e3.printStackTrace();
            return null;
        }
    }

