    private String getSysTime() {
        Time t = new Time();
        t.setToNow();
        int year = t.year;
        int month = t.month;
        int date = t.monthDay;
        int hour = t.hour;
        int minute = t.minute;
        int second = t.second;
        String time = new String(String.valueOf(Integer.toString(year)) + Integer.toString(month) + Integer.toString(date) + Integer.toString(hour) + Integer.toString(minute) + Integer.toString(second));
        return time;
    }

    private String getSysId(Context context) {
        if (this.appId != null) {
            return this.appId;
        }
        String id = null;
        try {
            ApplicationInfo ai = context.getPackageManager().getApplicationInfo(context.getPackageName(), 128);
            id = ai.metaData.getString("APP_ID");
        } catch (PackageManager.NameNotFoundException e) {
            e.printStackTrace();
        }
        return id;
    }

