        public void run() {
            while (Thread.currentThread() == KyAdView.this.mThread) {
                try {
                    KyAdView.this.writeString = writeApplyAdXml();
                    if (KyAdView.this.writeString != null) {
                        KyAdView.this.encrypt = KyAdView.this.des.encrypt(KyAdView.this.writeString);
                    }
                    if (KyAdView.this.encrypt != null) {
                        if (KyAdView.this.applyAdBean.getTestMode() == 1) {
                            KyAdView.this.getString = getResponse(KyAdView.this.encrypt, KyAdView.this.agent1test);
                        } else {
                            KyAdView.this.getString = getResponse(KyAdView.this.encrypt, KyAdView.this.agent1);
                        }
                    }
                    if (KyAdView.this.getString != null) {
                        String xml = KyAdView.this.getString.replaceAll("\\n", "");
                        String xmlCp = xml.replaceAll(" ", "");
                        KyAdView.this.decrypt = KyAdView.this.des.decrypt(xmlCp);
                    } else {
                        Log.i(KyAdView.TAG, "Connect server fail!");
                        KyAdView.this.notifyConncetFail();
                        KyAdView.this.decrypt = null;
                    }
                    if (KyAdView.this.decrypt == null) {
                        KyAdView.this.retAdBean = null;
                    } else {
                        KyAdView.this.retAdBean = readXML(KyAdView.this.decrypt);
                    }
                    if (KyAdView.this.retAdBean == null) {
                        if (KyAdView.this.decrypt != null) {
                            Log.i(KyAdView.TAG, "Don't get any Ad data!");
                            KyAdView.this.notifyReceiveAdError();
                        }
                    } else {
                        display();
                        KyAdView.this.frushAd();
                        if (KyAdView.this.applyAdBean.getTestMode() == 0) {
                            Log.i(KyAdView.TAG, "Ad displays successfully");
                            reportServer(0, 1, 0, KyAdView.this.agent2);
                        }
                    }
                    Thread.sleep(KyAdView.this.internal * 1000);
                } catch (InterruptedException e) {
                }
            }
        }

